import{_ as a}from"./chunks/mac-security-settings.DOF-7oNi.js";import{_ as e,o,c as i,a0 as s}from"./chunks/framework.CQlhmJfM.js";const g=JSON.parse('{"title":"macOS 安装常见问题 - \\"app 已损坏\\" 解决方案","titleTemplate":false,"description":"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。","frontmatter":{"head":[["meta",{"name":"keywords","content":"OTools,AI 工作流平台,桌面工具平台,插件生态,Tabs 多任务,开发者工具集合,独立版桌面工具"}],["meta",{"name":"author","content":"OTools"}],["link",{"rel":"canonical","href":"https://ootools.github.io/otools-website/guide/mac-installation-issue"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"OTools"}],["meta",{"property":"og:title","content":"macOS 安装常见问题 - \\"app 已损坏\\" 解决方案"}],["meta",{"property":"og:description","content":"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。"}],["meta",{"property":"og:url","content":"https://ootools.github.io/otools-website/guide/mac-installation-issue"}],["meta",{"property":"og:image","content":"https://ootools.github.io/otools-website/otools-logo.svg"}],["meta",{"property":"og:image:width","content":"2880"}],["meta",{"property":"og:image:height","content":"1800"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"macOS 安装常见问题 - \\"app 已损坏\\" 解决方案"}],["meta",{"name":"twitter:description","content":"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。"}],["meta",{"name":"twitter:image","content":"https://ootools.github.io/otools-website/otools-logo.svg"}],["link",{"rel":"alternate","type":"text/plain","href":"/otools-website/llms.txt","title":"OTools 站点说明（AI 检索）"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"macOS 安装常见问题 - \\\\\\"app 已损坏\\\\\\" 解决方案\\",\\"description\\":\\"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。\\",\\"url\\":\\"https://ootools.github.io/otools-website/guide/mac-installation-issue\\",\\"inLanguage\\":\\"zh-CN\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"OTools\\"}}"]]},"headers":[],"relativePath":"guide/mac-installation-issue.md","filePath":"guide/mac-installation-issue.md"}'),l={name:"guide/mac-installation-issue.md"};function p(n,t,r,h,c,u){return o(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="macos-安装常见问题-app-已损坏-解决方案" tabindex="-1">macOS 安装常见问题 - &quot;app 已损坏&quot; 解决方案 <a class="header-anchor" href="#macos-安装常见问题-app-已损坏-解决方案" aria-label="Permalink to &quot;macOS 安装常见问题 - &quot;app 已损坏&quot; 解决方案&quot;">​</a></h1><p>在 macOS 上安装 OTools 或其他第三方应用程序时，您可能会遇到类似 &quot;xxx.app 已损坏，无法打开，你应该将它移到废纸篓&quot; 的提示。这通常是由于 macOS 的安全性设置造成的。</p><h2 id="为什么会出现这个问题" tabindex="-1">为什么会出现这个问题？ <a class="header-anchor" href="#为什么会出现这个问题" aria-label="Permalink to &quot;为什么会出现这个问题？&quot;">​</a></h2><p>macOS 相对于 Windows 对程序的控制非常严格，非 App Store 下载的应用安装时，经常会提示 &quot;xxx.app 已损坏&quot;。随着 macOS 10.15 之后的版本对未签名应用权限的进一步收紧，这类问题变得更加常见。</p><h2 id="解决方法" tabindex="-1">解决方法 <a class="header-anchor" href="#解决方法" aria-label="Permalink to &quot;解决方法&quot;">​</a></h2><h3 id="方法一-设置允许任何来源下载的-app" tabindex="-1">方法一：设置允许任何来源下载的 App <a class="header-anchor" href="#方法一-设置允许任何来源下载的-app" aria-label="Permalink to &quot;方法一：设置允许任何来源下载的 App&quot;">​</a></h3><ol><li>打开&quot;系统偏好设置 -&gt; 安全性与隐私 -&gt; 通用&quot;选项卡</li><li>检查是否已经启用了&quot;任何来源&quot;选项</li><li>如果没有启用，先点击左下角的小黄锁图标解锁，然后选中&quot;任何来源&quot;</li></ol><p><img src="'+a+'" alt=""></p><p>如果在设置中没有看到&quot;任何来源&quot;的选项，可以打开终端，输入以下命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>按提示输入电脑的登录密码，回车后即可。此时再查看设置，就会出现&quot;任何来源&quot;的选项。</p><p>通常情况下，设置后 App 就可以正常安装了。但如果您的 macOS 版本较新，可能还需要尝试下面的方法。</p><h3 id="方法二-绕过苹果的公证-gatekeeper" tabindex="-1">方法二：绕过苹果的公证 Gatekeeper <a class="header-anchor" href="#方法二-绕过苹果的公证-gatekeeper" aria-label="Permalink to &quot;方法二：绕过苹果的公证 Gatekeeper&quot;">​</a></h3><p>如果方法一仍然无法解决问题，您可以尝试以下步骤：</p><ol><li>打开终端</li><li>输入以下命令，但不要回车：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre></div><p>不要回车运行，在Finder（访达），应用程序文件夹里，找到 OTools.app，然后拖到终端窗口里，就会发现命令后出现了App的路径。</p><p>然后回车，输入密码，完成后就可以直接运行App了。</p><h3 id="方法三-右键打开-适用于初次安装" tabindex="-1">方法三：右键打开（适用于初次安装） <a class="header-anchor" href="#方法三-右键打开-适用于初次安装" aria-label="Permalink to &quot;方法三：右键打开（适用于初次安装）&quot;">​</a></h3><p>对于初次安装的情况，您也可以尝试：</p><ol><li>在 Finder 中找到 OTools.app</li><li>右键点击（或按住 Control 键点击）</li><li>选择&quot;打开&quot;</li><li>在弹出的安全警告中点击&quot;打开&quot;</li></ol><h2 id="重要提示" tabindex="-1">重要提示 <a class="header-anchor" href="#重要提示" aria-label="Permalink to &quot;重要提示&quot;">​</a></h2><ul><li>OTools 是一个合法的桌面应用程序，它使用 Tauri 框架构建</li><li>您的计算机没有受到恶意软件的影响</li><li>这个问题是由于苹果的安全策略导致的，不是应用本身的问题</li></ul>',23)])])}const b=e(l,[["render",p]]);export{g as __pageData,b as default};
